  'pets.greet.nao.bird': [P, 'Pet greeting (staged): you watch; Nao holds an arm out low for the bird, then a hand to the satchel strap (no pecking it).', 'tests/e2e/staging_chapters.mjs --ch=misc (tests/e2e/staging_misc_cases.mjs; 1 branch)'],
  'pets.greet.nao.cat': [P, 'Pet greeting (staged): you watch; Nao crouches (held through the scene) with the letters held out, and nods: received.', 'tests/e2e/staging_chapters.mjs --ch=misc (tests/e2e/staging_misc_cases.mjs; 1 branch)'],
