  'pets.greet.ren.bird': [P, 'Pet greeting (staged): you watch; Ren leans to look at the bird, a hand to the chin (no dictionary yet), a nod.', 'tests/e2e/staging_chapters.mjs --ch=misc (tests/e2e/staging_misc_cases.mjs; 1 branch)'],
